-- Versatile player positions (primary stays on card.position)
DELETE FROM match_result;
DELETE FROM processed_event;
DELETE FROM auction_round;
DELETE FROM session_player_cards;
DELETE FROM session_player;
DELETE FROM game_session;

DROP TABLE IF EXISTS card_eligible_position;

CREATE TABLE card_eligible_position (
    card_id UUID NOT NULL REFERENCES card(id) ON DELETE CASCADE,
    position VARCHAR(10) NOT NULL,
    PRIMARY KEY (card_id, position)
);

DELETE FROM card;

